    function testFuzz_property(address caller, uint256 someValue) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        uint256 beforeTotalDistributed = c.totalDistributed();
        uint256 beforeOwnerBalance = c.balanceOf(address(this));

        vm.prank(address(this));
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.balanceOf(address(this)) == c.totalDistributed());
    }
}
